// Normalização e Motor de Avaliação de Leilões vs FIPE / Mercado
const items = $input.all();
const results = [];

for (const item of items) {
  const lot = item.json;
  const bidPrice = Number(lot.bid_price || lot.initial_bid || 0);
  const marketRef = Number(lot.fipe_value || lot.market_value || lot.appraisal_value || 0);

  if (bidPrice <= 0 || marketRef <= 0) continue;

  // Custos Reais: 5% leiloeiro + R$ 1.500 despesas + 10% margem de reparo
  const auctionFee = bidPrice * 0.05;
  const repairBuffer = marketRef * 0.10;
  const totalCost = bidPrice + auctionFee + 1500 + repairBuffer;
  const netProfit = marketRef - totalCost;
  const netMarginPercent = (netProfit / marketRef) * 100;
  const discountVsRef = ((marketRef - bidPrice) / marketRef) * 100;

  let category = 'car_auction';
  if (lot.type === 'real_estate') category = 'real_estate_auction';
  if (lot.type === 'machinery' || lot.type === 'industrial') category = 'industrial_auction';

  let score = 50;
  let priority = 'NORMAL';

  if (netMarginPercent >= 35 || discountVsRef >= 60) {
    score = 95;
    priority = 'CRITICAL_BUG'; // Oportunidade extrema de arremate
  } else if (netMarginPercent >= 20 || discountVsRef >= 45) {
    score = 80;
    priority = 'HIGH';
  } else if (netMarginPercent >= 10) {
    score = 65;
    priority = 'NORMAL';
  }

  if (score >= 65) {
    results.push({
      json: {
        category: category,
        title: lot.title || `Lote ${lot.lot_number} - Leilão`,
        description: `Deságio: ${discountVsRef.toFixed(1)}% | Margem Líquida Est.: ${netMarginPercent.toFixed(1)}% (Lucro: R$ ${netProfit.toFixed(2)})`,
        original_price: marketRef,
        opportunity_price: bidPrice,
        discount_percentage: Number(discountVsRef.toFixed(2)),
        net_profit_estimate: Number(netProfit.toFixed(2)),
        fipe_or_market_ref: marketRef,
        location: lot.state || lot.city || 'Brasil',
        source_name: lot.auctioneer_name || 'Portal de Leilões',
        source_url: lot.url || 'https://leilao.exemplo.com',
        evaluation_score: score,
        priority: priority,
        raw_metadata: {
          netMarginPercent: Number(netMarginPercent.toFixed(2)),
          totalEstimatedCost: Number(totalCost.toFixed(2))
        }
      }
    });
  }
}

return results;
